<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import LoadingState from '../components/LoadingState.vue'; import { useExamStore } from '../stores/exam'; import { allQuestions } from '../services/testLoader'; import { validateTestContent } from '../services/validation'
const route=useRoute(); const store=useExamStore(); const testId=String(route.params.testId); const test=ref(); onMounted(async()=>{try{test.value=await store.ensureTest(testId)}catch{}}); const count=computed(()=>test.value?allQuestions(test.value).length:0); const issues=computed(()=>test.value?validateTestContent(test.value):[])
</script>
<template><div class="page narrow"><LoadingState :loading="store.loading" :error="store.error"/><template v-if="test"><p class="eyebrow">Test introduction</p><h1>{{ test.metadata.title }}</h1><p class="lead">This full test covers all seven TOEIC Listening & Reading parts with {{ count }} original questions.</p><div class="intro-grid"><div><span>Difficulty</span><strong>{{ test.metadata.difficulty }}</strong></div><div><span>Target</span><strong>{{ test.metadata.targetScore }}</strong></div><div><span>Questions</span><strong>{{ count }}</strong></div></div><div v-if="issues.length" class="notice"><strong>Content validation</strong><p>{{ issues.length }} content validation notice(s).</p></div><div class="mode-grid"><RouterLink class="mode-card" :to="`/test/${testId}/practice`"><span>01</span><h2>Practice mode</h2><p>Choose a Part, replay audio, and reveal answers as you learn.</p></RouterLink><RouterLink class="mode-card dark" :to="`/test/${testId}/exam`"><span>02</span><h2>Exam mode</h2><p>Start Listening once for continuous Parts 1–4 playback, then complete Reading and submit for a raw score.</p></RouterLink></div></template></div></template>
